CREATE TABLE IF NOT EXISTS raw.downtime (event_date VARCHAR,line VARCHAR,event_id VARCHAR,machine VARCHAR,reason VARCHAR,downtime_minutes VARCHAR,planned_flag VARCHAR,_run_id VARCHAR NOT NULL,_report_id VARCHAR NOT NULL,_source_id VARCHAR NOT NULL,_source_file VARCHAR,_source_file_hash VARCHAR,_source_sheet VARCHAR,_source_row_number BIGINT,_extracted_at VARCHAR,_schema_version VARCHAR);
CREATE TABLE IF NOT EXISTS clean.downtime (event_date DATE NOT NULL,line VARCHAR NOT NULL,event_id VARCHAR NOT NULL,machine VARCHAR,reason VARCHAR,downtime_minutes DECIMAL(18,4) NOT NULL,planned_flag BOOLEAN,business_key_hash VARCHAR NOT NULL,row_content_hash VARCHAR NOT NULL,_run_id VARCHAR NOT NULL,_source_id VARCHAR,_source_file VARCHAR,_source_row_number BIGINT);
CREATE TABLE IF NOT EXISTS analytics.history_downtime (event_date DATE NOT NULL,line VARCHAR NOT NULL,event_id VARCHAR NOT NULL,machine VARCHAR,reason VARCHAR,downtime_minutes DECIMAL(18,4) NOT NULL,planned_flag BOOLEAN,business_key_hash VARCHAR NOT NULL,row_content_hash VARCHAR NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,first_seen_run_id VARCHAR NOT NULL,last_seen_run_id VARCHAR NOT NULL,_source_file VARCHAR,_source_row_number BIGINT);
